package ama.transcript;
import ama.storage.*;import ama.contract.FileContracts.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual factory, both binding entry points, SQL ordering and TransactionRunner rollback; fake rows/storage. */
class Task11DirectBindingGuardTest {
 static final String M=Task11PublicationWriteGuardBoundaryTest.MEETING,F="12345678-1234-4234-8234-123456789ac8",U="12345678-1234-4234-8234-123456789ac7",P="12345678-1234-4234-8234-123456789ac9",Q="12345678-1234-4234-8234-123456789ad0",H="a".repeat(64);static final ama.contract.IdentityContracts.Actor ACTOR=Task11PublicationWriteGuardBoundaryTest.ACTOR;
 static final class Case {
  final Task11PublicationWriteGuardBoundaryTest.Fixture f;final FileReferencePolicy policy=mock(FileReferencePolicy.class);final FileRegistry registry;boolean ready;
  Case()throws Exception{this(new Task11PublicationWriteGuardBoundaryTest.Fixture());}
  Case(Task11PublicationWriteGuardBoundaryTest.Fixture fixture)throws Exception{f=fixture;f.allowUpdates=true;when(policy.prelock(any(),eq(M),any(),anyString())).thenReturn(new Object());when(f.access.lock(ACTOR,M)).thenReturn(f.root);var backend=mock(FileBackendCatalog.Backend.class);when(backend.type()).thenReturn("LOCAL");var backends=mock(FileBackendCatalog.class,call->call.getMethod().getName().equals("requireHistoricalMetadata")?backend:org.mockito.Answers.RETURNS_DEFAULTS.answer(call));registry=JdbcTranscriptAuthority.create(f.ds,f.tx,f.access,(a,m,p)->{},backends,Map.of("SAVED_TEST",policy),f.authority.readBudget(),f.authority.canonicalBudget()).registry();f.parameterResponder=(sql,params)->{var result=rows(sql);if(result!=null&&(P.equals(params.get(1))||Q.equals(params.get(1)))&&(sql.contains(" FROM upload_session ")||sql.contains(" FROM file_object "))){var changed=new ArrayList<Map<String,Object>>();for(var row:result){var copy=new LinkedHashMap<String,Object>();row.forEach((k,v)->copy.put(k,F.equals(v)?P:U.equals(v)?Q:v));changed.add(copy);}return changed;}return result;};}
  List<Map<String,Object>> rows(String sql){
   if(sql.startsWith("SELECT cancel_epoch FROM meeting "))return List.of(Map.of("cancel_epoch",0L));
   if(ready&&sql.contains(" FROM publication "))return sql.startsWith("SELECT COUNT(*)")?List.of(Map.of("count",1L)):List.of(Task11ImportPublicationGuardTest.row("id",P,"meeting_id",M,"confirmation_id",P,"business_key",P+":"+P,"library_id","library","folder_id","folder","state","READY","revision",1L));
   if(sql.startsWith("SELECT COUNT(*)"))return null;
   if(sql.startsWith("SELECT COALESCE(OCTET_LENGTH(")){var row=new LinkedHashMap<String,Object>();for(int n=0;n<(sql.contains(" FROM upload_session ")?27:24);n++)row.put("m"+n,10L);return List.of(row);}
   Map<String,Object> row;
   if(sql.contains(" FROM upload_session "))row=Task11ImportPublicationGuardTest.row("id",U,"meeting_id",M,"purpose","TRANSCRIPT_INPUT","cancel_epoch",0L,"backend_id","local","namespace","files","object_key","ab/test","expected_size",8L,"expected_sha256",H,"state","COMPLETED","completed_file_id",F);
   else if(sql.contains(" FROM file_object "))row=Task11ImportPublicationGuardTest.row("id",F,"meeting_id",M,"backend_id","local","namespace","files","object_key","ab/test","size_bytes",8L,"sha256",H,"state","AVAILABLE","location_revision",1L,"reference_epoch",1L,"storage_type","LOCAL","display_name","source.txt");else return null;
   String columns=sql.substring(7,sql.indexOf(" FROM "));if(columns.equals("*"))return List.of(row);var selected=new LinkedHashMap<String,Object>();for(String col:columns.split(","))selected.put(col,row.get(col));return List.of(selected);
  }
  void bind(boolean sources,boolean failSecond){var plan=registry.prepareWrite(ACTOR,M);f.tx.required(()->{var gate=registry.lockWrite(ACTOR,M,plan);var first=registry.prelock(gate,new FileRegistry.Reference("SAVED_TEST",F,"TRANSCRIPT_INPUT"),F);var bindings=new ArrayList<FileRegistry.Binding>();bindings.add(new FileRegistry.Binding(first,1,null));if(failSecond){var second=registry.prelock(gate,new FileRegistry.Reference("SAVED_TEST",P,"TRANSCRIPT_INPUT"),P);bindings.add(new FileRegistry.Binding(second,1,null));doAnswer(x->{if(((FileRegistry.Reference)x.getArgument(2)).ownerId().equals(P))throw new Conflict();return null;}).when(policy).validate(any(),eq(M),any(),any(),eq("TRANSCRIPT_INPUT"));}var acquired=sources?registry.prelockSources(gate,failSecond?List.of(F,P):List.of(F),false).orElseThrow():null;try{if(sources)registry.bindAll(acquired,bindings);else registry.bindAll(bindings);}catch(Conflict denied){if(!failSecond)throw denied;}return null;});}
 }
 @Test void ordinaryBindingBothFormsAcquiresCompleteGuardBeforeWrites()throws Exception{for(boolean sources:List.of(false,true)){var c=new Case();c.bind(sources,false);assertEquals(2,c.f.updates.size());int write=c.f.sql.indexOf(c.f.updates.getFirst());assertTrue(c.f.sql.subList(0,write).stream().anyMatch(s->s.contains("publication_submission")));assertTrue(c.f.sql.subList(0,write).stream().anyMatch(s->s.contains("file_object")&&s.endsWith("FOR UPDATE")));}}
 @Test void readyPublicationFencesBothFormsBeforeAnyReferenceWrite()throws Exception{for(boolean sources:List.of(false,true)){var c=new Case();c.ready=true;assertThrows(ama.contract.MinutesContracts.Failure.class,()->c.bind(sources,false));assertTrue(c.f.updates.isEmpty());}}
 @Test void caughtSecondBindingFailureMustRollbackTheFirstBindingInBothForms()throws Exception{for(boolean sources:List.of(false,true)){var c=new Case();assertThrows(org.springframework.transaction.UnexpectedRollbackException.class,()->c.bind(sources,true));assertEquals(2,c.f.updates.size());assertEquals(1,c.f.rollbacks.get());assertEquals(0,c.f.commits.get());}}

 @Test void completeClosedLocalAndRemoteHistoryAllowsBothActualBindingForms()throws Exception{
  for(boolean remote:List.of(false,true))for(boolean sources:List.of(false,true)){
   var history=remote?new Task11ClosedHistoryFixture.Fixture().remote():new Task11ClosedHistoryFixture.Fixture().local();var original=Map.copyOf(history.originals);var c=new Case(Task11ClosedHistoryGuardTest.sql(history,new java.util.concurrent.atomic.AtomicBoolean()));c.bind(sources,false);assertEquals(2,c.f.updates.size());assertEquals(2,c.f.commits.get());assertEquals(original,history.originals);assertTrue(c.f.updates.stream().noneMatch(sql->sql.contains("publication")||sql.contains("external_execution")));
  }
 }
}
